                    if ($u === 'PRIMARY') {
                        $type = 'PRIMARY_KEY';
                    } elseif ($u === 'UNIQUE') {
                        $type = 'UNIQUE';
                    } elseif ($u === 'CHECK') {
                        $type = 'CHECK';
                    } elseif ($u === 'FOREIGN') {
                        $type = 'FOREIGN_KEY';
